import{_ as a,o as t,c as n,a2 as o}from"./chunks/framework.qEx7tieT.js";const p=JSON.parse('{"title":"Drawings","description":"","frontmatter":{},"headers":[],"relativePath":"guide/drawings.md","filePath":"guide/drawings.md"}'),s={name:"guide/drawings.md"};function i(r,e,d,c,h,g){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="drawings" tabindex="-1">Drawings <a class="header-anchor" href="#drawings" aria-label="Permalink to &quot;Drawings&quot;">​</a></h1><p><code>mosaic svg-pack drawing.svg</code> packs an SVG into an archive of one node, named after the file and given a made-up id the way a converted glTF node is. There is no conversion in the sense the glTF and IFC readers convert — those take a file apart into the components that describe it, because a mesh is not one thing but buffers and accessors and primitives. An SVG is already a description of a drawing, so taking it apart would only lose it. It travels whole, under <code>w3c::svg</code>: a W3C format rather than a Khronos one, so it gets a namespace of its own beside <code>khronos::gltf</code>.</p><p>A glb has nowhere native to put a drawing, so it rides on its node as <code>MOSAIC_components</code> extension data — and a node carrying one is written into the scene even though it has no mesh, since it is carrying something. The viewer asks for <code>w3c::svg</code> alongside the glTF components and turns the markup into geometry with three&#39;s own SVG reader, at the last moment, which is the only place that decision belongs. Note that reader draws paths and shapes but not <code>&lt;text&gt;</code>.</p>',3)])])}const m=a(s,[["render",i]]);export{p as __pageData,m as default};
